// builder_c.asm -- RNDP Replicator 2 (compact layout) builder, Hack-vN-AB.  Reads the layout data (lay_data.asm, generated by tools/lay2asm.py --hack
// from the placer/router output) and builds a copy of the machine through the arm: PLACE ROM and arm, PLACE every NAND/DFF site, PLACE the RAM,
// copy the ROM image (PROGRAM_ROM), then lay one routed path per sink (TRACK / VIA), ports last (EN is the last port), the RUN sinks after them, halt.
// All coordinates are relative to the parent's arm; the child's arm is at x = CHILD_DX.  NAND pins: A (x,y) B (x,y+1) Y (x+1,y); DFF D (x,y) Q (x+1,y).
// Arm registers: 0,1 A.x  2,3 A.y  4,5 B.x  6,7 B.y  8 KIND  9 ANGLE  10 VAL  15 CMD.  CMD 1 PLACE, 3 PROGRAM_ROM, 4 TRACK (VAL = layer), 5 VIA.
// Segment byte: [7] last  [6] via  [5:4] direction (0 +x, 1 -x, 2 +y, 3 -y)  [3:0] length; length 0: the next byte is the length (0 there: no path).

.equ ARM,      ARM_BASE

start:
    SET AUH, 0               // add16 addend high byte is 0 between calls
    // ---- the child's ROM and arm first (PROGRAM_ROM needs the ROM; nothing is wired before the image is copied)
    WR16 0, CHILD_DX+ROM_X   // A.x
    WR16 2, ROM_Y            // A.y
    WRK 8, 2                 // KIND = ROM
    WRK 9, ROM_ROT           // ANGLE
    WRK 10, ROM_AB           // VAL = ROM address bits
    WRK 15, 1                // PLACE
    WR16 0, CHILD_DX+ARM_X   // the child's arm
    WR16 2, ARM_Y
    WRK 8, 3                 // KIND = ARM
    WRK 9, ARM_ROT
    WRK 10, 0
    WRK 15, 1                // PLACE
    WRK 9, 0                 // ANGLE = 0 for every NAND and DFF
    // ---- every NAND / DFF site (row-major).  The kinds come from the exception list at lay_kinds.
    SET16 KP, lay_kinds
    CALL kinit               // SKIPL, NEXTK = first entry
    SET16 SY, GY0
    SET ROWL, ROWS
pl_row:
    SET16 SX, CHILD_DX+GX0
    SET COLL, COLS
pl_col:
    CALL sitekind            // KINDV
    @KINDV
    D=M
    @2
    D=D-A
    IFEQ pl_skip             // empty site
    WRA 0, SX
    WRA 1, SX+1
    WRA 2, SY
    WRA 3, SY+1
    WRA 8, KINDV             // 0 NAND / 1 DFF
    WRK 15, 1                // PLACE
pl_skip:
    ADDI SX, PX
    @COLL
    M=M-1
    D=M
    IFNE pl_col
    ADDI SY, PY
    @ROWL
    M=M-1
    D=M
    IFNE pl_row
    // ---- the RAM part
    WR16 0, CHILD_DX+RAM_X
    WR16 2, RAM_Y
    WRK 8, 4                 // KIND = RAM
    WRK 9, RAM_ROT
    WRK 10, RAM_AB           // VAL = address width
    WRK 15, 1                // PLACE
    WRK 8, 0                 // KIND, ANGLE, VAL back to 0
    WRK 9, 0
    WRK 10, 0
    // ---- program the child's ROM with this ROM's image (before anything is wired); zero bytes need no command
    WR16 0, CHILD_DX+ROM_X   // A = the child's ROM origin
    WR16 2, ROM_Y
    SET16 CA, 0              // ROM offset 0
    SET16 P, ROM_BASE        // read pointer = start of this ROM
    SET PSEL, P
rom_loop:
    CALL rdb                 // D = ROM byte at P; P += 1
    ST LEN                   // keep it
    IFEQ rom_skip            // zero: nothing to program
    WRA 4, CA                // B.x low = offset
    WRA 5, CA+1              // B.x high
    WRA 10, LEN              // VAL = byte
    WRK 15, 3                // PROGRAM_ROM
rom_skip:
    INC16 CA                 // next offset
    LD P
    @lo(lay_end)
    D=D-A
    IFNE rom_loop
    LD P+1
    @hi(lay_end)
    D=D-A
    IFNE rom_loop
    // ---- the paths of all node pins: sites in the same order as above, pin A then B (a DFF has only D)
    SET16 PD, lay_paths
    SET16 KP, lay_kinds
    CALL kinit
    SET16 SY, GY0
    SET ROWL, ROWS
wr_row:
    SET16 SX, CHILD_DX+GX0
    SET COLL, COLS
wr_col:
    CALL sitekind
    @KINDV
    D=M
    @2
    D=D-A
    IFEQ wr_skip             // empty site: no pins
    COPY16 CX, SX            // pin A at (x, y)
    COPY16 CY, SY
    CALL dpath
    LD KINDV
    IFNE wr_skip             // DFF: one pin only
    COPY16 CX, SX            // pin B at (x, y+1)
    COPY16 CY, SY
    ADDI CY, 1
    CALL dpath
wr_skip:
    ADDI SX, PX
    @COLL
    M=M-1
    D=M
    IFNE wr_col
    ADDI SY, PY
    @ROWL
    M=M-1
    D=M
    IFNE wr_row
    // ---- ports (EN last), start cells from the table
    SET16 TP, lay_port_starts
    SET NP, NPORTS
pt_loop:
    CALL tabpt               // CX, CY = next start cell
    CALL dpath
    @NP
    M=M-1
    D=M
    IFNE pt_loop
    // ---- RUN sinks last
    SET16 TP, lay_run_starts
    SET NP, NRUN
run_loop:
    CALL tabpt
    CALL dpath
    @NP
    M=M-1
    D=M
    IFNE run_loop
halt:                        // finished: the child is built; the model's halt convention
    GOTO halt

// ================================================================================================== subroutines
tabpt:                       // CX, CY = the next 4 bytes of the table at TP
    SET PSEL, TP
    CALL rdb
    ST CX
    CALL rdb
    ST CX+1
    CALL rdb
    ST CY
    CALL rdb
    ST CY+1
    RET tabpt

kinit:                       // read the first exception entry at KP
    SET PSEL, KP
    CALL rdb
    ST SKIPL
    CALL rdb
    ST NEXTK
    RET kinit

sitekind:                    // KINDV = kind of the next site
    LD SKIPL
    IFEQ sk_exc              // zero: this site is the exception
    D=D-1
    ST SKIPL
    SET KINDV, 0
    RET sitekind
sk_exc:
    LD NEXTK
    ST KINDV
    SET PSEL, KP
    CALL rdb
    ST SKIPL
    CALL rdb
    ST NEXTK
    RET sitekind

getlen:                      // LEN = BYT & 15, or the next stream byte when that is 0; D = LEN
    LD BYT
    @15
    D=D&A
    ST LEN
    IFNE gl_done
    CALL rdb                 // extended length
    ST LEN
gl_done:
    LD LEN
    RET getlen

dpath:                       // lay the path starting at (CX, CY), reading segment bytes at PD
    SET PSEL, PD
    CALL rdb
    ST BYT
    CALL getlen
    IFNE dp_go
    RET dpath                // no path
dp_go:
    LD BYT                   // first segment: via bit = start layer
    @64
    D=D&A
    IFEQ dp_l0
    SET LAYER, 1
    GOTO dp_lset
dp_l0:
    SET LAYER, 0
dp_lset:
    WRA 10, LAYER
dp_seg:                      // BYT, LEN describe the segment that starts at (CX, CY)
    WRA 0, CX                // A = current point
    WRA 1, CX+1
    WRA 2, CY
    WRA 3, CY+1
    LD BYT
    @48
    D=D&A                    // direction * 16
    IFEQ dp_r
    @16
    D=D-A
    IFEQ dp_l
    @16
    D=D-A
    IFEQ dp_d
    // 3: -y
    LD LEN
    D=-D
    ST AUL
    SET AUH, 255
    SET ADST, CY
    CALL add16
    GOTO dp_emit
dp_r:                        // 0: +x
    LD LEN
    ST AUL
    SET ADST, CX
    CALL add16
    GOTO dp_emit
dp_l:                        // 1: -x
    LD LEN
    D=-D
    ST AUL
    SET AUH, 255
    SET ADST, CX
    CALL add16
    GOTO dp_emit
dp_d:                        // 2: +y
    LD LEN
    ST AUL
    SET ADST, CY
    CALL add16
dp_emit:
    WRA 4, CX                // B = new point
    WRA 5, CX+1
    WRA 6, CY
    WRA 7, CY+1
    WRK 15, 4                // TRACK
    LD BYT
    IFLT dp_done             // bit 7: last segment
    SET PSEL, PD
    CALL rdb
    ST BYT
    CALL getlen
    LD BYT
    @64
    D=D&A
    IFEQ dp_seg              // no via
    WRA 0, CX                // VIA at the current point
    WRA 1, CX+1
    WRA 2, CY
    WRA 3, CY+1
    WRK 15, 5
    LD LAYER                 // toggle the layer
    IFEQ dp_to1
    SET LAYER, 0
    GOTO dp_tset
dp_to1:
    SET LAYER, 1
dp_tset:
    WRA 10, LAYER
    GOTO dp_seg
dp_done:
    RET dpath

rdb:                         // D = ROM byte at the pointer whose RAM address is in PSEL; that pointer += 1
    @PSEL
    A=M                      // A = address of the pointer variable
    AP                       // A = the pointer's value (a ROM address)
    D=M                      // D = the ROM byte
    @RDV
    M=D                      // keep the byte
    @PSEL
    A=M
    M=M+1                    // pointer.low += 1
    D=M
    @rdb_done
    D;JNE                    // no carry unless the low byte became 0
    @PSEL
    A=M+1                    // A = address of pointer.high
    M=M+1                    // pointer.high += 1
rdb_done:
    @RDV
    D=M                      // D = the byte
    RET rdb

add16:                       // the 16-bit variable at RAM address ADST += (AUH:AUL), mod 2^16; AUH is cleared
    @ADST
    A=M                      // A = address of the variable (low byte)
    D=M                      // D = its low byte
    @AO
    M=D                      // AO = old low byte
    @AUL
    D=D+M                    // D = old + addend low (mod 256)
    @AN
    M=D                      // AN = new low byte
    @AO
    D=M
    @AUL
    D=D&M                    // old & addend
    @AC
    M=D
    @AO
    D=M
    @AUL
    D=D|M                    // old | addend
    @AX
    M=D
    @AN
    D=!M                     // ~new
    @AX
    D=D&M                    // (old | addend) & ~new
    @AC
    D=D|M                    // bit 7 of D is the carry out of the low byte
    @AH
    M=0                      // assume no carry
    @add16_nc
    D;JGE                    // bit 7 clear: no carry
    @AH
    M=1                      // carry
add16_nc:
    @AN
    D=M                      // D = new low byte
    @ADST
    A=M
    M=D                      // store the low byte
    @AUH
    D=M                      // D = addend high
    @AH
    D=D+M                    // D = addend high + carry
    @ADST
    A=M+1                    // A = address of the high byte
    M=D+M                    // high byte += D
    @AUH
    M=0                      // addend high is 0 again for the next caller
    RET add16
